        "entryPointId": "a1cc5e48-df3b-4eb1-90d7-63169ddce4dc",
        "isDefaultEntryPoint": true
      }
    },
    {
      "id": "managerReview",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "display": {
        "label": "Manager Review"
      },
